import Foundation

/// Encodes supported value properties using fixed constructors, properties and collection operations.
/// A Java runtime only receives output generated by this schema.
final class NativePuzzleBeanWriter {
    private static let schema: [String: Set<String>] = [
        "sudoku.Sudoku2": "cells fixed free initialState level score solution solutionSet status statusGivens unsolvedCellsAnz userCells values",
        "sudoku.GuiState": "anzSteps boxReasoningGroups boxReasoningRedoHistory boxReasoningUndoHistory chainIndex coloringMap coloringCandidateMap coloringUndoCells coloringUndoCandidates coloringRedoCells coloringRedoCandidates doodleHypothesisConsumedMask doodleHypothesisRedoMasks doodleHypothesisUndoMasks doodleRedoHistory doodleStrokes doodleUndoHistory includeAnnotations name redoStack step steps sudoku tabSteps timestamp titels undoStack userChainRedoHistory userChainUndoHistory userChains",
        "sudoku.SolutionStep": "alses authoredChainDiagram authoredPlacement baseEntities candidatesToDelete cannibalistic chains colorCandidates coverEntities endoFins entity entity2 entity2Number entityNumber fins generalizedProofs indices isSiamese potentialCannibalisticEliminations potentialEliminations progressScore progressScoreSingles progressScoreSinglesOnly restrictedCommons subType type values",
        "sudoku.Candidate": "index value",
        "sudoku.Chain": "chain end start",
        "sudoku.Entity": "entityName entityNumber",
        "sudoku.AlsInSolutionStep": "candidates chainPenalty indices",
        "sudoku.DoodlePoint": "x y",
        "sudoku.DoodleStroke": "anchorCell anchorDigit candidateMarkKind color conclusionOutlined conclusionSourceMask contradictionWitness derivedSourceId hypothesisConditionId hypothesisGroupKind hypothesisStart points proofOnly refutationResult thoughtGroup widthFactor",
        "sudoku.UserChain": "active analysisResult closed nextStrong nodes relationColors sourceId strongRelations",
        "sudoku.UserChainNode": "candidate cellIndex color groupCells memberCandidates",
        "sudoku.UserChainProof": "nodes truths",
        "sudoku.DifficultyLevel": "backgroundColor foregroundColor maxScore name ordinal type",
        "sudoku.SudokuSet": "all anz initialized mask1 mask2 values",
        "java.awt.Point": "x y", "java.awt.Color": "", "java.util.Date": "time",
        "java.util.ArrayList": "", "java.util.Stack": "", "java.util.LinkedList": "", "java.util.Vector": "",
        "java.util.HashMap": "", "java.util.TreeMap": ""
    ].mapValues { Set($0.split(separator: " ").map(String.init)) }
    private static let primitives: Set<String> = ["boolean","byte","short","int","long","float","double"]
    private static let enums: Set<String> = ["sudoku.SudokuStatus","sudoku.DifficultyType","sudoku.SolutionType"]
    private var emitted: [ObjectIdentifier: String] = [:]
    private var activeDefaults = Set<ObjectIdentifier>()
    private var work = 0

    private func string(_ text: String) -> String {
        var result = ""
        for s in text.unicodeScalars {
            switch s.value {
            case 38: result += "&amp;"
            case 60: result += "&lt;"
            case 62: result += "&gt;"
            case 0...8, 11...13, 14...31, 65534, 65535: result += "<char code=\"#\(String(s.value, radix: 16))\"/>"
            default: result.unicodeScalars.append(s)
            }
        }
        return result
    }
    func value(_ bean: LegacyBean) throws -> String {
        work += 1
        guard work < 2_000_000 else { throw NativePuzzleError.metadata }
        let type = bean.className
        if type == "null" { return "<null/>" }
        if type == "string", let s = bean.scalar { return "<string>" + string(s) + "</string>" }
        if Self.primitives.contains(type), let s = bean.scalar {
            let isNumber = type == "boolean" ? ["true","false"].contains(s)
                : (type == "float" || type == "double" ? Double(s)?.isFinite == true : Int64(s) != nil)
            guard isNumber else { throw NativePuzzleError.metadata }
            return "<\(type)>\(string(s))</\(type)>"
        }
        if Self.enums.contains(type), let name = bean.scalar,
           !name.isEmpty, name.utf8.allSatisfy({ (48...57).contains($0) || (65...90).contains($0) || $0 == 95 }) {
            return "<object class=\"java.lang.Enum\" method=\"valueOf\"><class>\(type)</class><string>\(name)</string></object>"
        }
        if type == "java.awt.Color", bean.scalar != nil {
            let rgb = try LegacySessionInk.rgb(bean)
            return "<object class=\"java.awt.Color\"><int>\(rgb >> 16)</int><int>\(rgb >> 8 & 255)</int><int>\(rgb & 255)</int></object>"
        }
        let key = ObjectIdentifier(bean)
        if let id = emitted[key] { return "<object idref=\"\(id)\"/>" }
        let id = "n\(emitted.count)"
        emitted[key] = id
        if type == "sudoku.DoodleCoordinates", let data = bean.compact {
            // SessionInkCodec validated the count/length. Reconstruct a plain List<DoodlePoint>
            // accepted by DoodleStroke.setPoints. Preserve all coordinates and shared lists.
            var points = ReplayJavaInput(data: data)
            guard try points.byte() == 1 else { throw NativePuzzleError.metadata }
            let count = try points.int()
            guard count >= 0, count <= 1_000_000, points.remaining == count * 16 else { throw NativePuzzleError.metadata }
            var xml = "<object class=\"java.util.ArrayList\" id=\"\(id)\">"
            for _ in 0..<count {
                let x = Double(bitPattern: try points.number(8)), y = Double(bitPattern: try points.number(8))
                guard x.isFinite, y.isFinite else { throw NativePuzzleError.metadata }
                xml += "<void method=\"add\"><object class=\"sudoku.DoodlePoint\"><double>\(x)</double><double>\(y)</double></object></void>"
            }
            return xml + "</object>"
        }
        if type.hasSuffix("[]"), let count = bean.length {
            let itemType = String(type.dropLast(2))
            guard Self.primitives.contains(itemType), count <= 1_000_000 else { throw NativePuzzleError.metadata }
            var xml = "<array class=\"\(itemType)\" length=\"\(count)\" id=\"\(id)\">"
            if bean.compact != nil {
                for (i, v) in try bean.integers().enumerated() where v != 0 {
                    let number = itemType == "boolean" ? "true" : String(v)
                    xml += "<void index=\"\(i)\"><\(itemType)>\(number)</\(itemType)></void>"
                }
            } else { xml += try children(bean) }
            return xml + "</array>"
        }
        guard Self.schema[type] != nil, bean.scalar == nil else { throw NativePuzzleError.metadata }
        var xml = "<object class=\"\(type)\" id=\"\(id)\">"
        let arguments = bean.arguments.map(\.className)
        let ordinary = ["java.awt.Color","java.awt.Point","java.util.Date"].contains(type) &&
            arguments.count <= 4 && arguments.allSatisfy(Self.primitives.contains)
        let doodle = type == "sudoku.DoodlePoint" && arguments == ["double","double"] ||
            type == "sudoku.DoodleStroke" && arguments.count == 2 &&
            ["java.awt.Color","null"].contains(arguments[0]) && arguments[1] == "float"
        guard arguments.isEmpty || ordinary || doodle else {
            throw NativePuzzleError.metadata
        }
        for arg in bean.arguments { xml += try value(arg) }
        return xml + (try children(bean)) + "</object>"
    }

    private func children(_ bean: LegacyBean) throws -> String {
        var xml = ""
        for key in bean.fields.keys.sorted() {
            guard let child = bean[key] else { throw NativePuzzleError.metadata }
            if bean.className == "sudoku.DoodleStroke" && key == "rgb" {
                guard let argb = Int32(exactly: try child.int()) else { throw NativePuzzleError.metadata }
                let bits = UInt32(bitPattern: argb)
                let channels = [16, 8, 0, 24].map { "<int>\((bits >> $0) & 255)</int>" }.joined()
                xml += "<void property=\"color\"><object class=\"java.awt.Color\">" + channels + "</object></void>"
                continue
            }
            guard Self.schema[bean.className]?.contains(key) == true else { throw NativePuzzleError.metadata }
            xml += "<void property=\"\(key)\">" + (try body(child)) + "</void>"
        }
        for i in bean.indexed.keys.sorted() {
            guard let child = bean.indexed[i], i >= 0 && i < (bean.length ?? 1_000_000) else { throw NativePuzzleError.metadata }
            xml += "<void index=\"\(i)\">" + (try body(child)) + "</void>"
        }
        for c in bean.elements { xml += "<void method=\"add\">" + (try value(c)) + "</void>" }
        for (k,v) in bean.entries { xml += "<void method=\"put\">" + (try value(k)) + (try value(v)) + "</void>" }
        return xml
    }

    private func body(_ child: LegacyBean) throws -> String {
        // A getter with nested void operations mutates an existing default collection/array.
        if child.className == "default" {
            let id = ObjectIdentifier(child)
            guard activeDefaults.insert(id).inserted else { throw NativePuzzleError.metadata }
            defer { activeDefaults.remove(id) }
            return try children(child)
        }
        return try value(child)
    }
}
